WITH scored AS (SELECT id, dept_name, location, budget, LEAD(budget, 1, 0) OVER w_hist AS next_budget, SUM(budget) OVER w_ordered AS cumulative_budget, MIN(budget) OVER (PARTITION BY dept_name, location) AS dept_name_min_budget FROM departments WINDOW w_hist AS (ORDER BY budget, id), w_ordered AS (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, dept_name, budget, cumulative_budget, dept_name_min_budget FROM scored ORDER BY dept_name_min_budget DESC
